WITH daily_loss AS (SELECT cr.cr_returned_date_sk AS return_date, w.w_warehouse_id, SUM(cr.cr_net_loss) AS daily_net_loss, COUNT(*) AS returns_count, MAX(cr.cr_return_amt_inc_tax) AS max_return_amount, MIN(cr.cr_return_amt_inc_tax) AS min_return_amount FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cr.cr_returned_date_sk, w.w_warehouse_id) SELECT return_date, w_warehouse_id, daily_net_loss, AVG(daily_net_loss) OVER (PARTITION BY w_warehouse_id ORDER BY return_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rolling_3_day_avg, CASE WHEN daily_net_loss > 1000 THEN 'Loss Spike' ELSE 'Normal' END AS loss_flag, returns_count, max_return_amount, min_return_amount FROM daily_loss ORDER BY return_date, w_warehouse_id LIMIT 200
